package view;

import bus.staff.StaffBUS;
import java.awt.*;
import java.io.File;
import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import model.auth.AuthenticatedSession;
import model.staff.StaffModels.Staff;
import view.component.UIStyle;

final class StaffPanel extends JPanel {
    private final AuthenticatedSession session; private final StaffBUS bus; private final boolean doctors;
    private final JTextField search=new JTextField(); private final DefaultTableModel model; private final JTable table;
    private final JPanel detail=new JPanel(new BorderLayout()); private final JButton edit=new JButton("Chỉnh sửa"); private Staff hovered;
    StaffPanel(AuthenticatedSession s,StaffBUS b,boolean d){session=s;bus=b;doctors=d;model=new DefaultTableModel(new Object[]{"Mã NV","Họ tên","Bộ phận","Chức danh","Chuyên khoa","Trạng thái","__row"},0){public boolean isCellEditable(int r,int c){return false;}};table=new JTable(model);setLayout(new BorderLayout(0,16));setBackground(MainFrame.PAGE);setBorder(BorderFactory.createEmptyBorder(25,28,30,28));add(header(),BorderLayout.NORTH);add(body(),BorderLayout.CENTER);edit.addActionListener(e->{if(hovered!=null)open(hovered);});load();}
    private JPanel header(){JPanel p=new JPanel(new BorderLayout());p.setOpaque(false);JPanel l=new JPanel();l.setOpaque(false);l.setLayout(new BoxLayout(l,BoxLayout.Y_AXIS));JLabel t=new JLabel(doctors?"Quản lý bác sĩ":"Quản lý nhân viên");t.setFont(new Font("Segoe UI",Font.BOLD,25));t.setForeground(MainFrame.TEXT);JLabel d=new JLabel("Danh sách gọn — rê chuột vào dòng để xem hồ sơ đầy đủ.");d.setForeground(MainFrame.MUTED);l.add(t);l.add(d);JButton add=new JButton("+ Thêm nhân viên");UIStyle.primaryButton(add);add.setVisible(session.hasPermission("NHANSU_SUA"));add.addActionListener(e->{new StaffDialog(SwingUtilities.getWindowAncestor(this),session,bus,null,doctors).setVisible(true);load();});p.add(l,BorderLayout.WEST);p.add(add,BorderLayout.EAST);return p;}
    private JPanel body(){JPanel outer=new JPanel(new BorderLayout(14,0));outer.setOpaque(false);JPanel list=new JPanel(new BorderLayout(0,12));list.setBackground(Color.WHITE);list.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(MainFrame.BORDER),BorderFactory.createEmptyBorder(16,16,16,16)));search.setPreferredSize(new Dimension(380,36));search.putClientProperty("JTextField.placeholderText","Tìm mã, họ tên, số điện thoại...");list.add(search,BorderLayout.NORTH);UIStyle.table(table);table.setRowHeight(40);table.setAutoCreateRowSorter(true);table.getColumnModel().getColumn(6).setMinWidth(0);table.getColumnModel().getColumn(6).setMaxWidth(0);table.getColumnModel().getColumn(6).setWidth(0);table.addMouseMotionListener(new java.awt.event.MouseMotionAdapter(){public void mouseMoved(java.awt.event.MouseEvent e){int r=table.rowAtPoint(e.getPoint());if(r>=0)showDetail((Staff)table.getValueAt(table.convertRowIndexToModel(r),6));}});list.add(new JScrollPane(table),BorderLayout.CENTER);search.addActionListener(e->load());outer.add(list,BorderLayout.CENTER);outer.add(detailCard(),BorderLayout.EAST);return outer;}
    private JPanel detailCard(){detail.setPreferredSize(new Dimension(330,0));detail.setBackground(Color.WHITE);detail.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(MainFrame.BORDER),BorderFactory.createEmptyBorder(0,0,12,0)));showEmptyDetail();return detail;}
    private void showEmptyDetail(){detail.removeAll();JPanel head=cardHeader("HỒ SƠ NHÂN SỰ","Chọn một dòng để xem chi tiết");JLabel hint=new JLabel("Rê chuột vào danh sách bên trái",SwingConstants.CENTER);hint.setForeground(MainFrame.MUTED);hint.setBorder(BorderFactory.createEmptyBorder(20,12,20,12));detail.add(head,BorderLayout.NORTH);detail.add(hint,BorderLayout.CENTER);detail.revalidate();detail.repaint();}
    private JPanel cardHeader(String title,String subtitle){JPanel h=new JPanel(new BorderLayout(10,0));h.setBackground(MainFrame.NAVY);h.setBorder(BorderFactory.createEmptyBorder(14,16,14,16));JLabel avatar=avatar(hovered,title);JPanel text=new JPanel();text.setOpaque(false);text.setLayout(new BoxLayout(text,BoxLayout.Y_AXIS));JLabel a=new JLabel(title);a.setForeground(Color.WHITE);a.setFont(new Font("Segoe UI",Font.BOLD,14));JLabel b=new JLabel(subtitle);b.setForeground(new Color(190,215,226));b.setFont(new Font("Segoe UI",Font.PLAIN,12));text.add(a);text.add(Box.createVerticalStrut(4));text.add(b);h.add(avatar,BorderLayout.WEST);h.add(text,BorderLayout.CENTER);return h;}
    private JLabel avatar(Staff x,String fallback){JLabel label=new JLabel();label.setPreferredSize(new Dimension(52,52));label.setHorizontalAlignment(SwingConstants.CENTER);label.setVerticalAlignment(SwingConstants.CENTER);label.setOpaque(true);label.setBackground(new Color(0x02B5AB));label.setForeground(Color.WHITE);label.setFont(new Font("Segoe UI",Font.BOLD,18));String path=x==null?null:x.avatarPath();if(path!=null&&!path.isBlank()&&new File(path).isFile()){ImageIcon source=new ImageIcon(path);Image image=source.getImage().getScaledInstance(52,52,Image.SCALE_SMOOTH);label.setIcon(new ImageIcon(image));label.setText("");}else{String value=fallback==null?"NV":fallback.trim();label.setText(value.isEmpty()?"NV":value.substring(0,Math.min(2,value.length())).toUpperCase());}return label;}
    private void showDetail(Staff x){if(x==null||x==hovered)return;hovered=x;detail.removeAll();JPanel head=cardHeader(x.name(),x.id());JPanel body=new JPanel();body.setBackground(Color.WHITE);body.setBorder(BorderFactory.createEmptyBorder(14,18,10,18));body.setLayout(new BoxLayout(body,BoxLayout.Y_AXIS));JLabel badge=new JLabel(statusText(x.status()));badge.setOpaque(true);badge.setBackground(statusColor(x.status()));badge.setForeground(Color.WHITE);badge.setBorder(BorderFactory.createEmptyBorder(5,9,5,9));body.add(badge);body.add(Box.createVerticalStrut(14));body.add(group("Thông tin liên hệ",new String[]{"Giới tính",safe(x.gender()),"Ngày sinh",safe(x.birth()),"Điện thoại",safe(x.phone()),"Email",safe(x.email()),"Địa chỉ",safe(x.address())}));body.add(Box.createVerticalStrut(12));body.add(group("Công việc",new String[]{"Bộ phận",safe(x.departmentName()),"Chức danh",safe(x.titleName()),"Ngày bắt đầu",safe(x.startDate())}));if(x.doctor()){body.add(Box.createVerticalStrut(12));body.add(group("Chuyên môn",new String[]{"Học vị",safe(x.degree()),"Chuyên môn",safe(x.specialty()),"Chuyên khoa",safe(x.specialtyId()),"Chứng chỉ",safe(x.license())}));}JScrollPane scroll=new JScrollPane(body);scroll.setBorder(null);scroll.getVerticalScrollBar().setUnitIncrement(12);JPanel actions=new JPanel(new GridLayout(1,2,8,0));actions.setBorder(BorderFactory.createEmptyBorder(10,18,0,18));actions.setBackground(Color.WHITE);UIStyle.secondaryButton(edit);edit.setEnabled(session.hasPermission("NHANSU_SUA"));JButton refresh=new JButton("Làm mới");UIStyle.secondaryButton(refresh);refresh.addActionListener(e->load());actions.add(refresh);actions.add(edit);detail.add(head,BorderLayout.NORTH);detail.add(scroll,BorderLayout.CENTER);detail.add(actions,BorderLayout.SOUTH);detail.revalidate();detail.repaint();}
    private JPanel group(String title,String[] data){JPanel p=new JPanel();p.setOpaque(false);p.setLayout(new BoxLayout(p,BoxLayout.Y_AXIS));JLabel h=new JLabel(title);h.setFont(new Font("Segoe UI",Font.BOLD,12));h.setForeground(MainFrame.TEXT);p.add(h);p.add(Box.createVerticalStrut(7));for(int i=0;i<data.length;i+=2){JPanel row=new JPanel(new BorderLayout(8,0));row.setOpaque(false);JLabel k=new JLabel(data[i]);k.setForeground(MainFrame.MUTED);JLabel v=new JLabel("<html>"+data[i+1]+"</html>");v.setForeground(MainFrame.TEXT);row.add(k,BorderLayout.WEST);row.add(v,BorderLayout.CENTER);p.add(row);p.add(Box.createVerticalStrut(5));}return p;}
    private static String statusText(String s){return switch(s==null?"":s){case "DangLam"->"Đang làm việc";case "ThuViec"->"Thử việc";case "TamNghi"->"Tạm nghỉ";case "DaNghi"->"Đã nghỉ";default->safe(s);};}
    private static Color statusColor(String s){return "DangLam".equals(s)?new Color(38,157,105):"DaNghi".equals(s)?new Color(142,151,163):new Color(218,145,43);}
    private static String safe(Object x){return x==null||x.toString().isBlank()?"Chưa cập nhật":x.toString();}
    private Staff selected(){int r=table.getSelectedRow();return r<0?hovered:(Staff)table.getValueAt(table.convertRowIndexToModel(r),6);}
    private void open(Staff x){if(x==null)x=selected();if(x==null)return;new StaffDialog(SwingUtilities.getWindowAncestor(this),session,bus,x,doctors).setVisible(true);load();}
    private void load(){new SwingWorker<java.util.List<Staff>,Void>(){protected java.util.List<Staff> doInBackground(){return bus.find(session,search.getText(),doctors);}protected void done(){try{model.setRowCount(0);for(Staff x:get())model.addRow(new Object[]{x.id(),x.name(),x.departmentName(),x.titleName(),doctors?x.specialty():"—",statusText(x.status()),x});hovered=null;showEmptyDetail();}catch(Exception e){UIStyle.showError(StaffPanel.this,e.getCause()==null?e.getMessage():e.getCause().getMessage());}}}.execute();}
}
